package dev.goforge.containers;
import com.google.gson.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class DevContainerImageTest {
    private JsonObject image(String metadata){var root=new JsonObject();root.addProperty("Id","sha256:"+"a".repeat(64));var config=new JsonObject();var labels=new JsonObject();if(metadata!=null)labels.addProperty("devcontainer.metadata",metadata);config.add("Labels",labels);root.add("Config",config);return root;}
    @Test public void plainAndExplicitlyEmptyMetadataAreAcceptedWithPinnedIdentity(){assertEquals("sha256:"+"a".repeat(64),DevContainerImage.verify(image(null)));assertEquals("sha256:"+"a".repeat(64),DevContainerImage.verify(image("[]")));}
    @Test public void inheritedMountsPrivilegesAndHooksCannotBypassBasicProjection(){for(String metadata:new String[]{"[{\"mounts\":[\"source=/,target=/host,type=bind\"]}]","[{\"privileged\":true}]","[{\"initializeCommand\":\"touch /host\"}]","{\"capAdd\":[\"SYS_ADMIN\"]}"})assertThrows(IllegalArgumentException.class,()->DevContainerImage.verify(image(metadata)));}
    @Test public void malformedMetadataAndNonImmutableIdentityAreRejected(){assertThrows(IllegalArgumentException.class,()->DevContainerImage.verify(image("not json")));var invalid=image(null);invalid.addProperty("Id","image:mutable");assertThrows(IllegalArgumentException.class,()->DevContainerImage.verify(invalid));}
    private DevContainerPlan plan(){return new DevContainerPlan(java.nio.file.Path.of("/workspace"),java.nio.file.Path.of("/workspace/devcontainer.json"),"hash","owner","goforge-name","/workspaces/test","{}","{}","null",java.util.List.of());}
    private JsonObject container(){var result=JsonParser.parseString("{\"Image\":\"sha256:"+"a".repeat(64)+"\",\"Name\":\"/goforge-name\",\"Config\":{\"Labels\":{\"dev.goforge.workspace\":\"owner\"}},\"HostConfig\":{},\"Mounts\":[{\"Type\":\"bind\",\"Source\":\"/workspace\",\"Destination\":\"/workspaces/test\"}]}").getAsJsonObject();result.getAsJsonArray("Mounts").get(0).getAsJsonObject().addProperty("Source",plan().workspace().toString());return result;}
    @Test public void existingContainerMustMatchImageOwnerNameAndApprovedBind(){DevContainerImage.verifyContainer(plan(),"sha256:"+"a".repeat(64),container());var wrongImage=container();wrongImage.addProperty("Image","sha256:"+"b".repeat(64));assertThrows(IllegalStateException.class,()->DevContainerImage.verifyContainer(plan(),"sha256:"+"a".repeat(64),wrongImage));var wrongMount=container();wrongMount.getAsJsonArray("Mounts").get(0).getAsJsonObject().addProperty("Source","/");assertThrows(IllegalStateException.class,()->DevContainerImage.verifyContainer(plan(),"sha256:"+"a".repeat(64),wrongMount));}
    @Test public void existingContainerCannotSmuggleMetadataOrHostPrivileges(){var privileged=container();privileged.getAsJsonObject("HostConfig").addProperty("Privileged",true);assertThrows(IllegalStateException.class,()->DevContainerImage.verifyContainer(plan(),"sha256:"+"a".repeat(64),privileged));var metadata=container();metadata.getAsJsonObject("Config").getAsJsonObject("Labels").addProperty("devcontainer.metadata","[{\"privileged\":true}]");assertThrows(IllegalArgumentException.class,()->DevContainerImage.verifyContainer(plan(),"sha256:"+"a".repeat(64),metadata));}
    @Test public void onlyReferenceCliMetadataMatchingTheApprovedPlanCanBeReused(){var p=plan();var configured=new DevContainerPlan(p.workspace(),p.source(),p.sourceHash(),p.owner(),p.name(),p.workspaceFolder(),"{\"userEnvProbe\":\"none\",\"overrideCommand\":true,\"updateRemoteUserUID\":false}",p.original(),p.lifecycle(),p.omitted());var safe=container();safe.getAsJsonObject("Config").getAsJsonObject("Labels").addProperty("devcontainer.metadata","[{\"userEnvProbe\":\"none\",\"overrideCommand\":true,\"updateRemoteUserUID\":false}]");DevContainerImage.verifyContainer(configured,"sha256:"+"a".repeat(64),safe);safe.getAsJsonObject("Config").getAsJsonObject("Labels").addProperty("devcontainer.metadata","[{\"userEnvProbe\":\"loginShell\"}]");assertThrows(IllegalArgumentException.class,()->DevContainerImage.verifyContainer(configured,"sha256:"+"a".repeat(64),safe));}
}
